{"content": """"Finite-N self-consistency: F_N(K) = (1/N) sum_{|w|<K} sqrt(1-(w/K)^2).
Exact stationary response of a FINITE sample (partial locking branch).
If F_N(3) ~ 0.71 (measured for a=0 at N=2000), the anomaly is a finite-N
threshold shift, and the a=1 plateau solves R = F_N(3R).
"""
import numpy as np

def cauchy_sample(n, gamma=1.0, seed=7):
    r = np.random.default_rng(seed)
    return gamma * np.tan(np.pi * (r.random(n) - 0.5))

def F_N(om, K):
    w = np.abs(om)
    locked = w < K
    if locked.sum() == 0:
        return 0.0
    return float(np.sqrt(1 - (w[locked]/K)**2).mean())  # normalized by N via mean of subset? NO - must be /N

def F_N_proper(om, K):
    """(1/N) sum over locked of sqrt(1-(w/K)^2)"""
    w = np.abs(om)
    locked = w < K
    if locked.sum() == 0:
        return 0.0
    return float(np.sqrt(1 - (w[locked]/K)**2).sum() / om.size)

for N in [2000, 100000]:
    om = cauchy_sample(N, 1.0, seed=40)  # seed*13+1 style
    print(f'--- N={N} ---')
    for K in [1.5, 2.0, 2.5, 3.0, 3.6, 6.0, 10.0]:
        print(f'  K={K:5.1f}: F_N={F_N_proper(om,K):.4f}  (OA: {np.sqrt(max(0,1-2/K)):.4f})',
              flush=True)

# a=1 self-consistency fixed points: R = F_N(3R) for K0=3
print()
print('=== a=1, K0=3: R vs F_N(3R) fixed point search (N=2000,100k) ===')
for N in [2000, 100000]:
    om = cauchy_sample(N, 1.0, seed=40)
    rs = np.linspace(0.01, 0.9, 90)
    diffs = []
    for r in rs:
        d = r - F_N_proper(om, 3.0*r)
        diffs.append((r, d))
    # find sign changes
    print(f'N={N}:')
    for i in range(len(rs)-1):
        if diffs[i][1] * diffs[i+1][1] < 0:
            print(f'  fixed point near R={rs[i]:.4f} (diff {diffs[i][1]:+.4f} -> {diffs[i+1][1]:+.4f})')
    # also evaluate at R=0.57
    print(f'  R=0.570: F_N(1.71)={F_N_proper(om,3.0*0.570):.4f}, diff={0.570-F_N_proper(om,1.71):+.4f}', flush=True)", "path": "local_tests/finiteN_selfconsistency.py"}

{"content": """"
Streamlined branch scan + nucleation test.
Branches via vectorized grid; nucleation with one representative (a=2, K0=6).
"""
import numpy as np
from scipy.integrate import quad

def g(w): return 1.0/(np.pi*(1.0+w*w))
def I(B):
    if B <= 0: return 0.0
    return quad(lambda w: g(w)*np.sqrt(max(0.0,1-(w/B)**2)), -B, B, limit=200)[0]

def branches(a, K0, grid=None):
    h = lambda R: R - I(K0*R**a)
    if grid is None: grid = np.linspace(1e-3, 0.999, 600)
    vals = np.array([h(R) for R in grid])
    out = []
    for i in range(1, len(grid)):
        if vals[i-1] < 0 <= vals[i] or vals[i-1] > 0 >= vals[i]:
            lo, hi = grid[i-1], grid[i]
            for _ in range(40):
                mid = 0.5*(lo+hi)
                if h(mid) < 0: lo = mid
                else: hi = mid
            out.append(0.5*(lo+hi))
    return out

def simulate_R(a, K0, N=4000, T=120.0, dt=0.02, seed=11, seedR0=None):
    r = np.random.default_rng(seed)
    om = np.tan(np.pi*(r.random(N)-0.5))
    th = r.uniform(0, 2*np.pi, N)
    if seedR0:
        n0 = int(N*seedR0); psi0 = 0.3
        th[:n0] = psi0 + 0.05*r.standard_normal(n0)
    steps = int(T/dt); nw = max(1, int(0.2*steps)); buf = []
    for i in range(steps):
        z = np.exp(1j*th).mean()
        R = abs(z); psi = np.angle(z)
        th = (th + om*dt + K0*(R**a)*np.sin(psi-th)*dt) % (2*np.pi)
        buf.append(R)
        if len(buf) > nw: buf.pop(0)
    return float(np.mean(buf))

print("Branches R* = I(K0^a R) | roots of R - I(K0 R^a) = 0:")
for a in [0.0, 0.5, 1.0, 2.0]:
    for K0 in [3.0, 6.0]:
        print(f"  a={a:3.1f} K0={K0:4.1f}: {[f'{b:.4f}' for b in branches(a,K0)]}")
print("\nOnset scan (supercritical a<=1: R(seed~0) should jump near K0=2):")
for a in [0.0, 0.5, 1.0]:
    for K0 in [1.5, 2.0, 2.5, 3.0]:
        print(f"  a={a:3.1f} K0={K0:4.1f}: R_ss={simulate_R(a,K0,seedR0=0.02):.4f}")
print("\nNucleation (a=2, subcritical):")
for K0 in [5.0, 6.0]:
    for R0 in [0.03, 0.5]:
        print(f"  K0={K0:4.1f} seedR0={R0}: R_ss={simulate_R(2.0,K0,seedR0=R0):.4f}")", "path": "local_tests/branches_fast.py"}

