{"title": "Reflexive Kuramoto Escape Barrier: horizon vs nucleation across (N, K0, alpha, sigma)", "timeout_seconds": 3000, "script_content": "import numpy as np, json, os
from numba import njit, prange
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

OUT='.'
os.makedirs(OUT, exist_ok=True)

@njit(parallel=True, cache=False)
def batch(N, sig, K0, alpha, Rth, Tmax, dt, seeds):
    n=len(seeds); tv=np.full(n,Tmax); hit=np.zeros(n,np.int64)
    for jj in prange(n):
        s=(seeds[jj]*2654435761+98765)&0x7fffffff
        th=np.empty(N); om=np.empty(N)
        for k in range(N):
            s=(s*1103515245+12345)&0x7fffffff; th[k]=2*np.pi*((s+1)/2147483648.0)
        for k in range(N):
            s=(s*1103515245+12345)&0x7fffffff; u1=(s+1)/2147483648.0
            s=(s*1103515245+12345)&0x7fffffff; u2=(s+1)/2147483648.0
            om[k]=np.sqrt(-2*np.log(u1))*np.cos(2*np.pi*u2)
        t=0.0
        while t<Tmax:
            sr=0.0; si=0.0
            for k in range(N): sr+=np.cos(th[k]); si+=np.sin(th[k])
            R=np.sqrt(sr*sr+si*si)/N
            if R>Rth: hit[jj]=1; tv[jj]=t; break
            psi=np.arctan2(si,sr); K=K0*R**alpha
            for k in range(N):
                s=(s*1103515245+12345)&0x7fffffff; u1=(s+1)/2147483648.0
                s=(s*1103515245+12345)&0x7fffffff; u2=(s+1)/2147483648.0
                g=np.sqrt(-2*np.log(u1))*np.cos(2*np.pi*u2)
                th[k]=th[k]+(om[k]+K*np.sin(psi-th[k]))*dt+sig*np.sqrt(dt)*g
            t+=dt
    return tv,hit

def km_median(tv,hit):
    order=np.argsort(tv); tv=tv[order]; hit=hit[order]
    times=np.unique(tv); at_risk=len(tv); surv=1.0
    for tt in times:
        mask=tv==tt; d=int(hit[mask].sum()); at_risk-=int(mask.sum())
        if d>0: surv*=(1-d/(at_risk+d))
        if surv<=0.5: return float(tt)
    return float('nan')

seeds=np.arange(256).astype(np.int64)
Ns=[200,400,800,1600]
results={}
print("Scanning...", flush=True)
for alpha in [1.0,2.0]:
    for sig in [0.0,0.3,0.6]:
        for K0 in [1.0,1.5,2.0,2.5,3.0,4.0]:
            for N in Ns:
                tv,hit=batch(N,sig,K0,alpha,0.5,4000.0,0.05,seeds)
                cens=float(1-hit.mean()); med=km_median(tv,hit)
                key=f"a{alpha}_s{sig}_K{K0}_N{N}"
                results[key]=dict(alpha=alpha,sigma=sig,K0=K0,N=N,
                    escape_frac=float(hit.mean()),censored=cens,km_median=med,
                    mean_t=float(tv.mean()),p25=float(np.percentile(tv,25)),p75=float(np.percentile(tv,75)))
                print(f"a={alpha} s={sig} K={K0} N={N} esc={hit.mean():.3f} med={med:.2f}", flush=True)

json.dump(results, open(os.path.join(OUT,'barrier_results.json'),'w'), indent=1)

# ---- Analysis: N-scaling of escape time at fixed sigma=0 ----
fig, axes = plt.subplots(2,2, figsize=(13,10))
for ai,alpha in enumerate([1.0,2.0]):
    ax=axes[ai,0]
    for K0 in [1.0,1.5,2.0,2.5,3.0,4.0]:
        meds=[]; 
        for N in Ns:
            r=results[f"a{alpha}_s0.0_K{K0}_N{N}"]
            meds.append(r['km_median'] if not np.isnan(r['km_median']) else np.nan)
        ax.plot(Ns, meds, 'o-', label=f"K0={K0}")
    ax.set_xscale('log'); ax.set_yscale('log')
    ax.set_xlabel('N'); ax.set_ylabel('KM median escape time (sigma=0)')
    ax.set_title(f'alpha={alpha}: escape time vs N'); ax.legend(fontsize=8); ax.grid(True,alpha=0.3)
    ax=axes[ai,1]
    for K0 in [1.0,1.5,2.0,2.5,3.0,4.0]:
        ef=[results[f"a{alpha}_s0.0_K{K0}_N{N}"]['escape_frac'] for N in Ns]
        ax.plot(Ns, ef, 'o-', label=f"K0={K0}")
    ax.set_xscale('log'); ax.set_xlabel('N'); ax.set_ylabel('escape fraction (T=4000)')
    ax.set_title(f'alpha={alpha}: escape fraction vs N'); ax.legend(fontsize=8); ax.grid(True,alpha=0.3)
plt.suptitle('Reflexive Kuramoto escape: horizon (flat in N) vs barrier (grows in N)', fontsize=13)
plt.tight_layout(); plt.savefig(os.path.join(OUT,'barrier_N_scaling.png'), dpi=110)

# ---- sigma crossover test ----
fig2,axes2=plt.subplots(1,2,figsize=(13,5))
for ai,alpha in enumerate([1.0,2.0]):
    ax=axes2[ai]
    for sig in [0.0,0.3,0.6]:
        for K0 in [2.0,3.0,4.0]:
            ef=[results[f"a{alpha}_s{sig}_K{K0}_N{N}"]['escape_frac'] for N in Ns]
            ax.plot(Ns, ef, 'o--', label=f"s={sig},K={K0}")
    ax.set_xscale('log'); ax.set_xlabel('N'); ax.set_ylabel('escape fraction')
    ax.set_title(f'alpha={alpha}: noise suppresses escape'); ax.legend(fontsize=7); ax.grid(True,alpha=0.3)
plt.tight_layout(); plt.savefig(os.path.join(OUT,'sigma_crossover.png'), dpi=110)

# ---- N-exponent fit near threshold ----
fits={}
for alpha in [1.0,2.0]:
    for sig in [0.0,0.3,0.6]:
        for K0 in [1.5,2.0,2.5,3.0]:
            xs=[]; ys=[]
            for N in Ns:
                r=results[f"a{alpha}_s{sig}_K{K0}_N{N}"]
                if r['km_median'] and not np.isnan(r['km_median']) and r['km_median']>0:
                    xs.append(np.log(N)); ys.append(np.log(r['km_median']))
            if len(xs)>=3:
                b,a=np.polyfit(xs,ys,1)
                fits[f"a{alpha}_s{sig}_K{K0}"]=float(b)
json.dump(fits,open(os.path.join(OUT,'n_exponent_fits.json'),'w'),indent=1)
print("N-exponents (slope of log t_esc vs log N):")
for k,v in fits.items(): print(f"  {k}: {v:+.3f}")
print("DONE")
"}

