{"title": "World C Simulation: /tmp/fit.py", "script_content": "import json, math, numpy as np

r = json.load(open('barrier_sweep.json'))
rows = r['rows']
Ns = np.array([row['N'] for row in rows], float)
esc = np.array([row['n_escaped'] for row in rows], float)
M = np.array([row['M'] for row in rows], float)
Tmax = 400.0

def binom_nll(logA, logc, model):
    A = np.exp(logA)
    c = np.exp(logc) if model != 'power' else np.exp(logc)
    if model == 'power':
        tau = A * Ns**c
    elif model == 'exp':
        tau = A * np.exp(c * Ns)
    elif model == 'exp_sqrt':
        tau = A * np.exp(c * np.sqrt(Ns))
    p = 1 - np.exp(-Tmax / tau)
    p = np.clip(p, 1e-15, 1-1e-15)
    return -np.sum(esc*np.log(p) + (M-esc)*np.log(1-p))
